128	func TestCreateExchangeValidationLeavesNothing(t *testing.T) {
129		f := setupExchange(t)
130		other, _ := f.s.RegisterPatient(doc, "合成患者乙")
131		encOther, _ := f.s.AddEncounter(doc, other.ID, time.Time{})
132		recOther, _ := f.s.CreateDraft(doc, other.ID, encOther.ID, Diagnosis, "他人记录")
133		vOther, _ := f.s.ActivateRecord(doc, recOther.ID)
