135	
136		// 授权给 rcvB，与接收方 rcv 不符。
137		authB, err := f.s.Grant(doc, f.pid, rcvB.ID,
138			[]Scope{{EncounterID: f.e1, Category: Diagnosis}}, f.start, f.end)
