433		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag, f.ord}, "req-wait")
434		if err != nil {
435			t.Fatal(err)
436		}
437	
438		// 另一条同患者、同接收方、覆盖相同记录且在核对时刻仍有效的授权：
439		// 绑定授权到期后也不能用它替代。
440		otherAuth, err := f.s.Grant(doc, f.pid, rcv.ID,
441			[]Scope{{EncounterID: f.e1, Category: Diagnosis}, {EncounterID: f.e1, Category: Order}},
442			f.start, f.end.Add(24*time.Hour))
443		if err != nil {
444			t.Fatal(err)
445		}
446		_ = otherAuth
