854	func TestExchangePersistenceAcrossReopen(t *testing.T) {
855		dir := t.TempDir()
856		clk := &fakeClock{t: time.Date(2026, 4, 1, 8, 0, 0, 0, time.UTC)}
857		open := func() *Store {
