876		}
877		// 打包后更正：包固定在 v1。
878		if _, err := s.CorrectRecord(doc, rec.ID, 1, "当前v2", "事后更正"); err != nil {
879			t.Fatal(err)
880		}
881		if _, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, "重开前拒绝"); err != nil {
882			t.Fatal(err)
883		}
